import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class PromotionTest {
    static boolean ok = true;
    static void check(String label, boolean cond) {
        if (!cond) { ok = false; System.out.println("  FAIL: " + label); }
    }
    public static void main(String[] args) {
        Field f = new Field(20, 20);
        Random rand = Randomizer.getRandom();

        // exposeToDiseases: susceptible organism gets infected (prob forced to 1.0)
        Gazelle gazelle = new Gazelle(false, f, new Location(1, 1));
        Covid covid = new Covid(f);                 // affects Gazelle/Lion/Hyena
        covid.setProbability(1.0);
        gazelle.exposeToDiseases(new ArrayList<>(List.of(covid)), rand);
        check("susceptible gazelle infected", gazelle.isInfected());

        // exposeToDiseases: organism not in the disease's species stays clean
        Mouse mouse = new Mouse(false, f, new Location(3, 3));
        Covid covid2 = new Covid(f); covid2.setProbability(1.0);
        mouse.exposeToDiseases(new ArrayList<>(List.of(covid2)), rand);
        check("non-susceptible mouse not infected", !mouse.isInfected());

        // Latent behaviour preserved: lakes are NOT randomly infected even though
        // Leptospirosis lists "Lake" (WaterSources doesn't override -> no-op default)
        Lake lake = new Lake(false, f, new Location(5, 5));
        Leptospirosis lepto = new Leptospirosis(f); lepto.setProbability(1.0);
        lake.exposeToDiseases(new ArrayList<>(List.of(lepto)), rand);
        check("lake not randomly infected (latent behaviour kept)", !lake.isInfected());

        // stepTarget: organisms -> nursery; environmental actors -> population
        List<Actor> population = new ArrayList<>();
        List<Actor> nursery = new ArrayList<>();
        Gazelle g2 = new Gazelle(false, f, new Location(7, 7));
        Weather weather = new Weather(null);
        check("organism acts into nursery", g2.stepTarget(population, nursery) == nursery);
        check("weather acts into population", weather.stepTarget(population, nursery) == population);
        // weather is not susceptible (default no-op should not throw)
        weather.exposeToDiseases(new ArrayList<>(List.of(covid)), rand);

        System.out.println(ok
            ? "PASS: disease exposure + act-target promoted to Actor; behaviour preserved."
            : "FAIL: see above.");
    }
}
